+ '{type:"scatterpolar",r:[safety[2],versatile[2],readable[2],speed[2],safety[2]],theta:["Readability","Speed","Safety","Versatility","Readability"],name:"Pickle",fill:"toself",fillcolor:"rgba(255,107,107,0.15)",line:{color:"#ff6b6b"}}'
