/* SECTION 6 */
+ '<h2 class="l-title">6. OS & Dosya Sistemi İşlemleri</h2>'

+ '<p class="l-text">Python dosya sistemi işlemleri için iki büyük API sunar: klasik <code>os</code>/<code>os.path</code> modülü (fonksiyon tabanlı, Python 2\'den beri mevcut) ve modern <code>pathlib</code> modülü (nesne yönelimli, Python 3.4+). İkisi de çalışır, ama yeni kod için <code>pathlib</code> önerilen yaklaşımdır. Her ikisini de öğrenelim ki eski kodu okuyabilin ve modern kod yazabilesiniz.</p>'

+ '<div class="calc-compare"><div class="compare-col"><div class="compare-title">os.path (Klasik)</div><div class="compare-item">&bull; <code>os.path.join("a", "b")</code></div><div class="compare-item">&bull; <code>os.path.exists(yol)</code></div><div class="compare-item">&bull; <code>os.path.basename(yol)</code></div><div class="compare-item">&bull; <code>os.path.splitext(yol)</code></div><div class="compare-item">&bull; String tabanlı, fonksiyonel stil</div></div><div class="compare-col"><div class="compare-title">pathlib (Modern)</div><div class="compare-item">&bull; <code>Path("a") / "b"</code></div><div class="compare-item">&bull; <code>yol.exists()</code></div><div class="compare-item">&bull; <code>yol.name</code></div><div class="compare-item">&bull; <code>yol.suffix</code></div><div class="compare-item">&bull; Nesne yönelimli, zincirlenebilir</div></div></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON — pathlib (ÖNERİLEN)</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">from</span> pathlib <span class="kw">import</span> Path\n\n<span class="cm"># Yol oluşturma ve özellikler</span>\np = Path(<span class="str">"veri/raporlar/2024/satis.csv"</span>)\n<span class="fn">print</span>(p.name)       <span class="cm"># "satis.csv"</span>\n<span class="fn">print</span>(p.stem)       <span class="cm"># "satis"</span>\n<span class="fn">print</span>(p.suffix)     <span class="cm"># ".csv"</span>\n<span class="fn">print</span>(p.parent)     <span class="cm"># Path("veri/raporlar/2024")</span>\n<span class="fn">print</span>(p.parts)      <span class="cm"># ("veri", "raporlar", "2024", "satis.csv")</span>\n\n<span class="cm"># / operatörü ile yol oluşturma (platformlar arası!)</span>\ntaban = Path.<span class="fn">home</span>() / <span class="str">"projeler"</span> / <span class="str">"uygulamam"</span>\nyapilandirma_dizini = taban / <span class="str">"yapilandirma"</span>\n\n<span class="cm"># Dizin işlemleri</span>\nyapilandirma_dizini.<span class="fn">mkdir</span>(parents=<span class="kw">True</span>, exist_ok=<span class="kw">True</span>)  <span class="cm"># mkdir -p gibi</span>\n\n<span class="cm"># Glob desenleri ile dosya listeleme</span>\n<span class="kw">for</span> csv_dosya <span class="kw">in</span> Path(<span class="str">"veri"</span>).<span class="fn">glob</span>(<span class="str">"*.csv"</span>):\n    <span class="fn">print</span>(csv_dosya)\n\n<span class="cm"># Özyinelemeli glob — alt dizinlerdeki tüm .py dosyaları</span>\npy_dosyalar = <span class="fn">list</span>(Path(<span class="str">"kaynak"</span>).<span class="fn">rglob</span>(<span class="str">"*.py"</span>))\n\n<span class="cm"># Dosya meta verileri</span>\n<span class="kw">if</span> p.<span class="fn">exists</span>():\n    <span class="fn">print</span>(p.<span class="fn">stat</span>().st_size)       <span class="cm"># bayt cinsinden dosya boyutu</span>\n    <span class="fn">print</span>(p.<span class="fn">is_file</span>())            <span class="cm"># normal dosya ise True</span>\n    <span class="fn">print</span>(p.<span class="fn">is_dir</span>())             <span class="cm"># dizin ise True</span>\n\n<span class="cm"># Yeniden adlandır ve taşı</span>\np.<span class="fn">rename</span>(<span class="str">"veri/raporlar/2024/gelir.csv"</span>)\n\n<span class="cm"># Mutlak yola çözümle</span>\n<span class="fn">print</span>(Path(<span class="str">"."</span>).<span class="fn">resolve</span>())   <span class="cm"># /home/kullanici/projeler/uygulamam</span></code></pre></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON — OS İşlemleri</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> os\n<span class="kw">import</span> shutil\n<span class="kw">import</span> tempfile\n\n<span class="cm"># Ortam değişkenleri</span>\nev = os.environ.<span class="fn">get</span>(<span class="str">"HOME"</span>, <span class="str">"/tmp"</span>)\napi_anahtar = os.environ.<span class="fn">get</span>(<span class="str">"API_KEY"</span>)  <span class="cm"># ayarlanmamışsa None</span>\n\n<span class="cm"># Mevcut dizin</span>\n<span class="fn">print</span>(os.<span class="fn">getcwd</span>())            <span class="cm"># mevcut çalışma dizini</span>\nos.<span class="fn">chdir</span>(<span class="str">"/tmp"</span>)              <span class="cm"># dizin değiştir</span>\n\n<span class="cm"># Dizin içeriğini listele</span>\ngirdiler = os.<span class="fn">listdir</span>(<span class="str">"."</span>)   <span class="cm"># dosya isimleri listesi</span>\n\n<span class="cm"># Dizin ağacını özyinelemeli gez</span>\n<span class="kw">for</span> dizin_yolu, alt_dizinler, dosya_adlari <span class="kw">in</span> os.<span class="fn">walk</span>(<span class="str">"kaynak"</span>):\n    <span class="kw">for</span> dosya_adi <span class="kw">in</span> dosya_adlari:\n        tam_yol = os.path.<span class="fn">join</span>(dizin_yolu, dosya_adi)\n        <span class="fn">print</span>(tam_yol)\n\n<span class="cm"># shutil — üst düzey dosya işlemleri</span>\nshutil.<span class="fn">copy2</span>(<span class="str">"kaynak.txt"</span>, <span class="str">"hedef.txt"</span>)   <span class="cm"># meta veri ile kopyala</span>\nshutil.<span class="fn">copytree</span>(<span class="str">"kaynak_diz"</span>, <span class="str">"hedef_diz"</span>)  <span class="cm"># tüm dizini kopyala</span>\nshutil.<span class="fn">rmtree</span>(<span class="str">"eski_diz"</span>)               <span class="cm"># dizin ağacını sil</span>\nshutil.<span class="fn">move</span>(<span class="str">"dosya.txt"</span>, <span class="str">"arsiv/"</span>)      <span class="cm"># dosya veya dizin taşı</span>\n\n<span class="cm"># Geçici dosya ve dizinler</span>\n<span class="kw">with</span> tempfile.<span class="fn">NamedTemporaryFile</span>(mode=<span class="str">"w"</span>, suffix=<span class="str">".csv"</span>, delete=<span class="kw">False</span>) <span class="kw">as</span> f:\n    f.<span class="fn">write</span>(<span class="str">"geçici veri\\n"</span>)\n    <span class="fn">print</span>(f.name)   <span class="cm"># /tmp/tmp_abc123.csv</span>\n\n<span class="kw">with</span> tempfile.<span class="fn">TemporaryDirectory</span>() <span class="kw">as</span> gecici_dizin:\n    <span class="cm"># gecici_dizin blok bittiğinde otomatik silinir</span>\n    gecici_dosya = os.path.<span class="fn">join</span>(gecici_dizin, <span class="str">"veri.txt"</span>)\n    <span class="kw">with</span> <span class="fn">open</span>(gecici_dosya, <span class="str">"w"</span>) <span class="kw">as</span> f:\n        f.<span class="fn">write</span>(<span class="str">"geçici içerik"</span>)</code></pre></div>'

+ '<div class="calc-example"><div class="ce-label">GERÇEK DÜNYA ÖRNEĞİ</div><div class="ce-content"><strong>Toplu Dosya İşleyici</strong> — Bu dersteki her şeyi birleştiren yaygın bir kalıp: dosya keşfi için glob, güvenli I/O için bağlam yöneticileri, sağlamlık için istisna yönetimi ve gözlemlenebilirlik için loglama.</div></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PSEUDOCODE</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> json\n<span class="kw">import</span> logging\n<span class="kw">from</span> pathlib <span class="kw">import</span> Path\n\nlogger = logging.<span class="fn">getLogger</span>(<span class="str">"isleyici"</span>)\n\n<span class="kw">def</span> <span class="fn">veri_dosyalarini_isle</span>(girdi_dizini, cikti_dizini):\n    <span class="str">"""Tüm JSON dosyalarını oku, verileri dönüştür, sonuçları yaz."""</span>\n    girdi_yolu = Path(girdi_dizini)\n    cikti_yolu = Path(cikti_dizini)\n    cikti_yolu.<span class="fn">mkdir</span>(parents=<span class="kw">True</span>, exist_ok=<span class="kw">True</span>)\n\n    sonuclar = {<span class="str">"islenen"</span>: <span class="num">0</span>, <span class="str">"basarisiz"</span>: <span class="num">0</span>, <span class="str">"atlanan"</span>: <span class="num">0</span>}\n\n    <span class="kw">for</span> json_dosya <span class="kw">in</span> girdi_yolu.<span class="fn">glob</span>(<span class="str">"*.json"</span>):\n        <span class="kw">try</span>:\n            <span class="kw">with</span> <span class="fn">open</span>(json_dosya, encoding=<span class="str">"utf-8"</span>) <span class="kw">as</span> f:\n                veri = json.<span class="fn">load</span>(f)\n        <span class="kw">except</span> json.JSONDecodeError <span class="kw">as</span> e:\n            logger.<span class="fn">warning</span>(<span class="str">"Geçersiz JSON atlanıyor: %s (%s)"</span>, json_dosya.name, e)\n            sonuclar[<span class="str">"atlanan"</span>] += <span class="num">1</span>\n            <span class="kw">continue</span>\n\n        <span class="kw">try</span>:\n            donusturulmus = <span class="fn">donustur</span>(veri)\n            cikti_dosya = cikti_yolu / json_dosya.name\n            <span class="kw">with</span> <span class="fn">open</span>(cikti_dosya, <span class="str">"w"</span>, encoding=<span class="str">"utf-8"</span>) <span class="kw">as</span> f:\n                json.<span class="fn">dump</span>(donusturulmus, f, indent=<span class="num">2</span>)\n            sonuclar[<span class="str">"islenen"</span>] += <span class="num">1</span>\n            logger.<span class="fn">info</span>(<span class="str">"İşlendi: %s"</span>, json_dosya.name)\n        <span class="kw">except</span> Exception:\n            sonuclar[<span class="str">"basarisiz"</span>] += <span class="num">1</span>\n            logger.<span class="fn">exception</span>(<span class="str">"İşlenemedi: %s"</span>, json_dosya.name)\n\n    logger.<span class="fn">info</span>(<span class="str">"Tamamlandı. %s"</span>, sonuclar)\n    <span class="kw">return</span> sonuclar</code></pre></div>'

